WITH TAB AS (
SELECT #{embryoCode} EMBRYO_CODE FROM dual
) SELECT C.EMBRYO_CODE, C.EMBRYO_VERSION, C.CREATE_TIME, C.id, CASE WHEN R.ID IS NOT NULL THEN 'TRUE' ELSE 'FALSE' END IS_SCHEDULE_FLAG FROM T_PRODUCT_CONSTRUCTION_INFO C LEFT JOIN (SELECT R.EMBRYO_CODE, MAX(R.ID) ID FROM T_CX_SCHEDULE_RESULT R INNER JOIN T_CX_AUTO_SCHEDULE_RECORD SR ON SR.CX_BATCH_NO = R.CX_BATCH_NO AND SR.DEL_FLAG = '0' AND SR.STATUS = '0' WHERE R.SCHEDULE_DATE BETWEEN #{scheduleDate} - 7 AND #{scheduleDate} - 1 AND R.DEL_FLAG = '0' GROUP BY R.EMBRYO_CODE) R ON R.EMBRYO_CODE = C.EMBRYO_CODE WHERE C.DEL_FLAG = '0' AND C.EMBRYO_CODE IN (SELECT EMBRYO_CODE FROM TAB)
